    public String send(String legacyClaimRecord) {
        return http.post()
                .uri("/rxclaim/adjudicate")
                .contentType(MediaType.TEXT_PLAIN)
                .accept(MediaType.TEXT_PLAIN)
                .body(legacyClaimRecord)
                .retrieve()
                .body(String.class);
    }
}
